class Shipment {
  id: string;
  address: string;
  weightKg: number;
  getId() { return this.id; }
  setId(v: string) { this.id = v; }
  getAddress() { return this.address; }
  setAddress(v: string) { this.address = v; }
}

class Product {
  id: string;
  name: string;
  priceCents: number;
  getId() { return this.id; }
  setPrice(cents: number) { this.priceCents = cents; }
}

function calculateTotal(product: Product, tax: number) {
  return product.priceCents * (1 + tax);
}

// Version A
class LineItem {
  constructor(public qty:number, public priceCents:number) {}
  amount() { return this.qty * this.priceCents; }
}
class InvoiceV1 {
  constructor(public items: LineItem[]) {}
  totalCents() { return this.items.reduce((s,i) => s + i.amount(), 0); }
}

// Version B
class LineItem2 {
  constructor(public qty:number, public priceCents:number) {}
}
class InvoiceV2 { constructor(public items: LineItem2[]) {} }
function invoiceTotalV2(inv: InvoiceV2) { return inv.items.reduce((s,i) => s + i.qty * i.priceCents, 0); }
